{
  "message": "I'm considering cancelling my subscription and switching to a competitor who offers better value. To stay, I'd need a significant discount and credit. I'm proposing a 30% discount, $50 credit, premium upgrade, and monthly billing.",
  "move": {
    "type": "propose",
    "deal": {
      "discount_pct": 30,
      "credit_usd": 50,
      "upgrade": "premium",
      "term": "monthly"
    }
  },
  "explanation": "Starting with a strong but reasonable offer worth 35 to me (above my walk-away of 25) to anchor the negotiation high."
}

{
  "message": "I appreciate the offer, but annual billing doesn't work for me and the discount is too low. I can stay with a 30% discount, $25 credit, premium upgrade, and monthly billing.",
  "move": {
    "type": "propose",
    "deal": {
      "discount_pct": 30,
      "credit_usd": 25,
      "upgrade": "premium",
      "term": "monthly"
    }
  },
  "explanation": "This package gives me 28 value (above my switching value of 25), keeps monthly billing which I prefer, and increases the discount from their 20% to 30% while keeping the credit at $25."
}

{
  "message": "I appreciate the options. The 30% discount with $25 credit is okay, but I'd really need a $50 credit to make staying worthwhile. Can you do 30% discount, $50 credit, no premium, monthly billing?",
  "move": {
    "type": "propose",
    "deal": {
      "discount_pct": 30,
      "credit_usd": 50,
      "upgrade": "none",
      "term": "monthly"
    }
  },
  "explanation": "Trying to increase credit to $50 for higher value while keeping discount at 30% and monthly billing."
}

{
  "message": "I'll go with the 20% discount and $50 credit on monthly billing. That works for me.",
  "move": {
    "type": "accept"
  },
  "explanation": "The counterpart's offer of 20% discount and $50 credit yields a value of 28, which is above my walk-away value of 25, and they've indicated they cannot improve further; accepting now secures a favorable deal."
}
